#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    // Otimização de entrada e saída
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<long long> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    // Ordena os comprimentos dos palitinhos
    sort(a.begin(), a.end());

    long long ans = 0;

    // Para cada k fixo como o maior lado do triângulo,
    // utilizamos dois ponteiros para encontrar pares (i, j) tais que a[i] + a[j] > a[k].
    for (int k = 2; k < n; ++k) {
        int i = 0;
        int j = k - 1;
        while (i < j) {
            if (a[i] + a[j] > a[k]) {
                // Se a[i] + a[j] > a[k], então para todo índice m tal que i <= m < j,
                // temos a[m] + a[j] >= a[i] + a[j] > a[k].
                // Logo, existem (j - i) opções válidas de i para este j.
                ans += (j - i);
                j--;
            } else {
                i++;
            }
        }
    }

    cout << ans << "\n";

    return 0;
}
